Node* closest_node = nullptr;
float min_distance = std::numeric_limits<float>::max();

for (const auto& node : graph.SNodes()) {
    // Check if this node belongs to any non-footway road
    bool is_on_non_footway = false;
    auto node_roads = graph.get_node_to_roadmap().find(node.index_);

    if (node_roads != graph.get_node_to_roadmap().end()) {
        for (const auto* road : node_roads->second) {
            if (road->type != Model::Road::Type::Footway) {
                is_on_non_footway = true;
                break;
            }
        }
    }

    if (is_on_non_footway) {
        float dx = node.x - x;
        float dy = node.y - y;
        float distance = std::sqrt(dx * dx + dy * dy);

        if (distance < min_distance) {
            min_distance = distance;
            closest_node = &const_cast<Node&>(node);
        }
    }
}

return closest_node;

